IMMUTABLE_MESSAGE = "ontology_versions rows are immutable"


def _create_immutability_triggers() -> None:
    """Database-level guarantee that published ontology versions can never change."""
    dialect = op.get_bind().dialect.name
    if dialect == "sqlite":
        for action in ("UPDATE", "DELETE"):
            op.execute(
                f"CREATE TRIGGER trg_ontology_versions_no_{action.lower()} "
                f"BEFORE {action} ON ontology_versions "
                f"BEGIN SELECT RAISE(ABORT, '{IMMUTABLE_MESSAGE}'); END"
            )
    elif dialect == "postgresql":
        op.execute(
            "CREATE FUNCTION ols_reject_ontology_version_mutation() RETURNS trigger AS $$ "
            f"BEGIN RAISE EXCEPTION '{IMMUTABLE_MESSAGE}'; END; $$ LANGUAGE plpgsql"
        )
        op.execute(
            "CREATE TRIGGER trg_ontology_versions_immutable BEFORE UPDATE OR DELETE "
            "ON ontology_versions FOR EACH ROW EXECUTE FUNCTION ols_reject_ontology_version_mutation()"
        )


def _drop_immutability_triggers() -> None:
    dialect = op.get_bind().dialect.name
    if dialect == "sqlite":
        op.execute("DROP TRIGGER IF EXISTS trg_ontology_versions_no_update")
        op.execute("DROP TRIGGER IF EXISTS trg_ontology_versions_no_delete")
    elif dialect == "postgresql":
        op.execute("DROP TRIGGER IF EXISTS trg_ontology_versions_immutable ON ontology_versions")
        op.execute("DROP FUNCTION IF EXISTS ols_reject_ontology_version_mutation()")


